import {esc,fmt} from '../../ui/format.js';
import {TYPES,FIELDS,PROCESS,POOLS,effective} from '../../core/model.js';
import {DIAGRAMS,expandedNeeds,modelAudit} from '../../core/mbse.js';
import {RELATIONS} from '../../core/model.js';
export function repositoryView(ctx){const {m,result,baseline,search}=ctx;const n=id=>m.nodes.find(n=>n.id===id);return `<div class="panelhead"><h1>Repository de elemente</h1><button data-action="repo-new">+ Element</button></div><div class="row"><input id="search" placeholder="Caută nume sau tip…" value="${esc(search)}"><span class="muted small">Același ID în toate diagramele; compoziția și relațiile sunt partajate.</span></div><div class="panel tablewrap"><table><thead><tr><th>Element</th><th>Tip</th><th>Părinte</th><th>Alocări / relații</th><th></th></tr></thead><tbody>${m.nodes.filter(x=>(x.name+' '+TYPES[x.type]).toLowerCase().includes(search.toLowerCase())).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(TYPES[x.type])}</td><td>${esc(n(x.parent)?.name||'—')}</td><td>${m.edges.filter(e=>e.from===x.id||e.to===x.id).length}</td><td><button data-open="${esc(x.id)}">Deschide în diagramă ↗</button></td></tr>`).join('')}</tbody></table></div>`}
